const numero = String($input.item.json.fields['N° OC/CM'] || '');
let etiqueta = 'CM/OC';
if (numero.startsWith('46')) {
  etiqueta = 'CM';
} else if (numero.startsWith('45')) {
  etiqueta = 'OC';
}
const perfiles = $input.item.json.fields['Perfiles'] || $input.item.json.fields['Personal inicial asignado'] || 'sin especificar';
const jornada = $input.item.json.fields['Jornada de trabajo'] || 'sin especificar';
const notaCombinada = 'N° ' + etiqueta + ': ' + (numero || 'sin numero asignado') + '. Perfiles: ' + perfiles + '. Jornada de trabajo: ' + jornada + '.';

const hayPersonal = $input.item.json.fields['Hay personal inicial asignado?'];
const opcionSI = hayPersonal === 'Si' ? '● SI' : 'o SI';
const opcionNO = hayPersonal === 'Si' ? 'o NO' : '● NO';

const modalidadSeleccionada = $input.item.json.fields['Modalidad del servicio'];
const opcionPorDia = modalidadSeleccionada === 'Por día' ? '● Por día' : 'o Por día';
const opcionPorHora = modalidadSeleccionada === 'Por hora' ? '● Por hora' : 'o Por hora';
const opcionPorMes = modalidadSeleccionada === 'Por mes' ? '● Por mes' : 'o Por mes';
const opcionPorServicio = modalidadSeleccionada === 'Por servicio' ? '● Por servicio' : 'o Por servicio';

const condicionSeleccionada = $input.item.json.fields['Condición de pago'];
const opcionInmediata = condicionSeleccionada === 'Inmediata' ? '● Inmediata' : 'o Inmediata';
const opcion15 = condicionSeleccionada === '15 días F/F' ? '● 15 días F/F' : 'o 15 días F/F';
const opcion30 = condicionSeleccionada === '30 días F/F' ? '● 30 días F/F' : 'o 30 días F/F';
const opcion45 = condicionSeleccionada === '45 días F/F' ? '● 45 días F/F' : 'o 45 días F/F';
const opcion60 = condicionSeleccionada === '60 días F/F' ? '● 60 días F/F' : 'o 60 días F/F';
const opcion75 = condicionSeleccionada === '75 días F/F' ? '● 75 días F/F' : 'o 75 días F/F';

return { json: { ...$input.item.json, notaCombinada: notaCombinada, opcionSI: opcionSI, opcionNO: opcionNO, opcionPorDia: opcionPorDia, opcionPorHora: opcionPorHora, opcionPorMes: opcionPorMes, opcionPorServicio: opcionPorServicio, opcionInmediata: opcionInmediata, opcion15: opcion15, opcion30: opcion30, opcion45: opcion45, opcion60: opcion60, opcion75: opcion75 } };

const plazoInicio = $input.item.json.fields['Plazo inicio'];
const plazoFin = $input.item.json.fields['Plazo fin'];

const [anoInicio, mesInicio, diaInicio] = plazoInicio.split('-');
const [anoFin, mesFin, diaFin] = plazoFin.split('-');

const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const fechaEmisionRaw = $('Buscar fila del proveedor').item.json.fields['Fecha de emision'];
const [anioEm, mesEm, diaEm] = fechaEmisionRaw.split('-');
const fechaEmisionTexto = parseInt(diaEm) + ' de ' + meses[parseInt(mesEm)-1] + ' de ' + anioEm;

const inicioDate = new Date(plazoInicio);
const finDate = new Date(plazoFin);
const mesesContrato = Math.round((finDate - inicioDate) / (1000*60*60*24*30.44));
const valorMensual = $('Buscar fila de licitación').item.json.fields['Valor mensual estimado'];
const valorTotalContrato = Math.round(valorMensual * mesesContrato * 1.20);

const monedaContrato = $('Buscar fila de licitación').item.json.fields['Moneda'];
const valorTotalContratoTexto = valorTotalContrato.toLocaleString('es-AR') + ' ' + monedaContrato;

return { json: { ...$input.item.json, diaInicio: diaInicio, mesInicio: mesInicio, anoInicio: anoInicio, diaFin: diaFin, mesFin: mesFin, anoFin: anoFin, fechaEmisionTexto: fechaEmisionTexto, valorTotalContrato: valorTotalContrato, valorTotalContratoTexto: valorTotalContratoTexto } };
